CREATE TABLE public.students (turno text, periodo_ingresso character varying(32), periodo_letivo_atual character varying(32), semestre character varying(32), status_academico text, updated_at timestamp with time zone, grau_academico text, created_at timestamp with time zone, course character varying(255) NOT NULL, profile_id uuid, name character varying(255) NOT NULL, ra character varying(32) NOT NULL, id uuid NOT NULL);
CREATE TABLE public.student_risk_scores (trend_variation text, status_geografico text, detail_geografico text, explanation text NOT NULL, recommendation text NOT NULL, score_geografico integer NOT NULL, calculated_at timestamp with time zone, score_relacionamento integer NOT NULL, score_academico integer NOT NULL, score_financeiro integer NOT NULL, temporal_trend USER-DEFINED NOT NULL, category USER-DEFINED NOT NULL, overall_risk_score integer NOT NULL, student_id uuid NOT NULL, id uuid NOT NULL, detail_academico text, status_financeiro text, status_relacionamento text, detail_relacionamento text, detail_financeiro text, status_academico text);
CREATE TABLE public.student_requirements (student_id uuid NOT NULL, status USER-DEFINED NOT NULL, protocol character varying(64) NOT NULL, current_stage text NOT NULL, id uuid NOT NULL, description text, updated_at timestamp with time zone, created_at timestamp with time zone, title text NOT NULL, type text NOT NULL);
CREATE TABLE public.student_relationships (tema_relacionamento character varying(128), id uuid NOT NULL, student_id uuid NOT NULL, codigo_atendimento bigint, data_atendimento timestamp with time zone, motivo_contato text, motivo_evasao text, alternativa_permanencia text);
CREATE TABLE public.student_financials (servico_parcela character varying(64) NOT NULL, periodo_letivo character varying(16) NOT NULL, parcela integer NOT NULL, valor_original numeric NOT NULL, status_parcela USER-DEFINED NOT NULL, data_vencimento date, data_baixa date, created_at timestamp with time zone, student_id uuid NOT NULL, id uuid NOT NULL, bolsa_aluno character varying(128));
CREATE TABLE public.student_contacts (student_id uuid NOT NULL, sexo text, estado_civil text, estado character varying(2), cidade text, bairro text, created_at timestamp with time zone, idade integer);
CREATE TABLE public.student_academic_history (pct_nota_obtida numeric, created_at timestamp with time zone, periodo_academico_oferta character varying(32), aulas_ministradas integer, faltas_lancadas integer, nota_distribuida numeric, nota_obtida numeric, situacao USER-DEFINED NOT NULL, student_id uuid NOT NULL, disciplina text NOT NULL, pct_assiduidade numeric, arquivo_origem text, id uuid NOT NULL, ano_semestre_letivo character varying(16) NOT NULL, pct_faltas numeric);
CREATE TABLE public.requirement_steps (active boolean, step_date timestamp with time zone, title text NOT NULL, description text, id uuid NOT NULL, requirement_id uuid NOT NULL, order_index integer NOT NULL, completed boolean);
CREATE TABLE public.profiles (semester character varying(64), id uuid NOT NULL, role USER-DEFINED NOT NULL, created_at timestamp with time zone, updated_at timestamp with time zone, name character varying(255) NOT NULL, ra character varying(32), email character varying(255) NOT NULL, course character varying(255), avatar_url text);
CREATE TABLE public.documents (validity text, auth_code_prefix character varying(32), file_url text, description text, title text NOT NULL, category text NOT NULL, created_at timestamp with time zone, role_target USER-DEFINED NOT NULL, id uuid NOT NULL);
CREATE TABLE public.chat_sessions (created_at timestamp with time zone, last_message_preview text, title text NOT NULL, role_context USER-DEFINED NOT NULL, user_id uuid NOT NULL, id uuid NOT NULL, updated_at timestamp with time zone);
CREATE TABLE public.chat_messages (quick_replies jsonb, sender USER-DEFINED NOT NULL, session_id uuid NOT NULL, id uuid NOT NULL, text text NOT NULL, created_at timestamp with time zone, attachments jsonb, suggested_action jsonb);